-- Import manuale Compagnie Excel 27/10/2026 (1409 codici).
-- Eseguire TUTTO il file in una sola sessione SQL (tabella temporanea).
-- Agenzia = Codice. Nome anagrafica = Nome+Nome_segue (se Nome coincide col gruppo, resta solo Nome_segue).
-- Compagnia = GruppoCompagnia, con alias verso gruppi_compagnia gia presenti.
-- Mandato = compagnia_rapporti (codice_rapporto = codice agenzia).
-- IBAN IT da 27 caratteri -> conti_bancari.tipo agenzia, is_default false (l'indice ammette un solo default per tipo).
-- Le righe gia presenti si aggiornano per codice. Il tipo (agenzia/plurimandataria/...) non si cambia.
-- Le nuove righe entrano come plurimandataria, cosi il trigger di auto-rapporto non duplica il mandato.
-- Prova senza scrivere: sostituire l'ultimo COMMIT con ROLLBACK.
-- Unico gruppo nuovo: Plurimandatario. Gli altri nomi Excel puntano a gruppi gia in tabella.
BEGIN;
CREATE TEMP TABLE imp_comp_xlsx (
  codice text PRIMARY KEY,
  nome text NOT NULL,
  nome_segue text,
  indirizzo text, cap text, comune text, provincia text,
  telefono text, fax text, codice_fiscale text, partita_iva text,
  stato text, attiva boolean, ultima_scadenza date,
  gruppo_descrizione text NOT NULL,
  gruppo_codice text NOT NULL,
  gruppo_excel text,
  tipo_mandatario text, gruppo_statistico text,
  mail text, pec text, mail_ec text, mail_avvisi text,
  percentuale_ra numeric, iban text, intestato_a text
) ON COMMIT DROP;

SELECT s.gruppo_codice, s.gruppo_descrizione, true
FROM (
  SELECT DISTINCT gruppo_codice, gruppo_descrizione FROM imp_comp_xlsx
) s
WHERE NOT EXISTS (
  SELECT 1 FROM public.gruppi_compagnia g
  WHERE upper(trim(g.descrizione)) = upper(trim(s.gruppo_descrizione))
)
AND NOT EXISTS (
  SELECT 1 FROM public.gruppi_compagnia g WHERE upper(g.codice) = upper(s.gruppo_codice)
);

  codice, nome, nome_segue, nome_sede, tipo, gruppo_compagnia_id, gruppo_compagnia,
  indirizzo, cap, comune, provincia, telefono, fax, codice_fiscale, partita_iva,
  stato, attiva, ultima_scadenza_polizza, tipo_mandatario, gruppo_statistico,
  mail, pec, mail_ec, mail_avvisi, email_estratto_conto, email_messe_a_cassa,
  percentuale_ra, iban, intestato_a, nazione
)
SELECT
  s.codice, s.nome, s.nome_segue, s.nome, 'plurimandataria', g.id, g.descrizione,
  s.indirizzo, s.cap, s.comune, s.provincia, s.telefono, s.fax, s.codice_fiscale, s.partita_iva,
  s.stato, s.attiva, s.ultima_scadenza, s.tipo_mandatario, s.gruppo_statistico,
  s.mail, s.pec, s.mail_ec, s.mail_avvisi, s.mail_ec, s.mail_avvisi,
  s.percentuale_ra, s.iban, COALESCE(s.intestato_a, s.nome), 'Italia'
FROM imp_comp_xlsx s
JOIN public.gruppi_compagnia g ON upper(trim(g.descrizione)) = upper(trim(s.gruppo_descrizione))
WHERE NOT EXISTS (SELECT 1 FROM public.compagnie c WHERE lower(c.codice) = lower(s.codice));

UPDATE public.compagnie c SET
  nome = s.nome,
  nome_segue = s.nome_segue,
  nome_sede = s.nome,
  gruppo_compagnia_id = g.id,
  gruppo_compagnia = g.descrizione,
  indirizzo = s.indirizzo,
  cap = s.cap,
  comune = s.comune,
  provincia = s.provincia,
  telefono = s.telefono,
  fax = s.fax,
  codice_fiscale = s.codice_fiscale,
  partita_iva = s.partita_iva,
  stato = s.stato,
  attiva = s.attiva,
  ultima_scadenza_polizza = s.ultima_scadenza,
  tipo_mandatario = s.tipo_mandatario,
  gruppo_statistico = s.gruppo_statistico,
  mail = s.mail,
  pec = s.pec,
  mail_ec = s.mail_ec,
  mail_avvisi = s.mail_avvisi,
  email_estratto_conto = s.mail_ec,
  email_messe_a_cassa = s.mail_avvisi,
  percentuale_ra = s.percentuale_ra,
  iban = s.iban,
  intestato_a = COALESCE(s.intestato_a, c.intestato_a, s.nome)
FROM imp_comp_xlsx s
JOIN public.gruppi_compagnia g ON upper(trim(g.descrizione)) = upper(trim(s.gruppo_descrizione))
WHERE lower(c.codice) = lower(s.codice);

UPDATE public.compagnia_rapporti r SET
  compagnia_id = c.id,
  gruppo_compagnia_id = c.gruppo_compagnia_id,
  nome_rapporto = c.nome,
  tipo_rapporto = COALESCE(r.tipo_rapporto, 'Mandato diretto'),
  attivo = c.attiva,
  percentuale_ra = c.percentuale_ra,
  iban_dedicato = c.iban,
  email_estratto_conto = c.mail_ec,
  email_messe_a_cassa = c.mail_avvisi,
  sede_denominazione = c.nome_sede,
  sede_indirizzo = c.indirizzo,
  sede_cap = c.cap,
  sede_citta = c.comune,
  sede_provincia = c.provincia,
  is_principale = CASE
    WHEN r.is_principale THEN true
    WHEN NOT EXISTS (
      SELECT 1 FROM public.compagnia_rapporti o
      WHERE o.compagnia_id = c.id AND o.is_principale AND o.id <> r.id
    ) THEN true
    ELSE false
  END,
  updated_at = now()
FROM public.compagnie c
JOIN imp_comp_xlsx s ON lower(s.codice) = lower(c.codice)
WHERE lower(r.codice_rapporto) = lower(c.codice);

UPDATE public.compagnia_rapporti r SET
  gruppo_compagnia_id = c.gruppo_compagnia_id,
  codice_rapporto = c.codice,
  nome_rapporto = c.nome,
  attivo = c.attiva,
  percentuale_ra = c.percentuale_ra,
  iban_dedicato = c.iban,
  email_estratto_conto = c.mail_ec,
  email_messe_a_cassa = c.mail_avvisi,
  sede_denominazione = c.nome_sede,
  sede_indirizzo = c.indirizzo,
  sede_cap = c.cap,
  sede_citta = c.comune,
  sede_provincia = c.provincia,
  updated_at = now()
FROM public.compagnie c
JOIN imp_comp_xlsx s ON lower(s.codice) = lower(c.codice)
WHERE r.compagnia_id = c.id
  AND r.is_principale
  AND lower(COALESCE(r.codice_rapporto, '')) <> lower(c.codice)
  AND NOT EXISTS (
    SELECT 1 FROM public.compagnia_rapporti o
    WHERE lower(o.codice_rapporto) = lower(c.codice)
  );

  compagnia_id, gruppo_compagnia_id, codice_rapporto, tipo_rapporto, nome_rapporto,
  attivo, percentuale_ra, iban_dedicato, email_estratto_conto, email_messe_a_cassa,
  sede_denominazione, sede_indirizzo, sede_cap, sede_citta, sede_provincia, is_principale
)
SELECT
  c.id, c.gruppo_compagnia_id, c.codice, 'Mandato diretto', c.nome,
  COALESCE(c.attiva, true), c.percentuale_ra, c.iban, c.mail_ec, c.mail_avvisi,
  c.nome_sede, c.indirizzo, c.cap, c.comune, c.provincia,
  NOT EXISTS (SELECT 1 FROM public.compagnia_rapporti o WHERE o.compagnia_id = c.id AND o.is_principale)
FROM public.compagnie c
JOIN imp_comp_xlsx s ON lower(s.codice) = lower(c.codice)
WHERE c.gruppo_compagnia_id IS NOT NULL
  AND NOT EXISTS (
    SELECT 1 FROM public.compagnia_rapporti r WHERE lower(r.codice_rapporto) = lower(c.codice)
  )
  AND NOT EXISTS (
    SELECT 1 FROM public.compagnia_rapporti r WHERE r.compagnia_id = c.id AND r.is_principale
  );

  etichetta, iban, intestato_a, banca, tipo, is_default, attivo, compagnia_id
)
SELECT
  'Conto ' || c.codice, c.iban, COALESCE(c.intestato_a, c.nome), 'Banca da definire',
  'agenzia', false, true, c.id
FROM public.compagnie c
JOIN imp_comp_xlsx s ON lower(s.codice) = lower(c.codice)
WHERE c.iban IS NOT NULL
  AND c.conto_bancario_id IS NULL
  AND NOT EXISTS (
    SELECT 1 FROM public.conti_bancari cb
    WHERE cb.compagnia_id = c.id AND replace(upper(cb.iban), ' ', '') = c.iban
  );

UPDATE public.compagnie c SET conto_bancario_id = cb.id
FROM public.conti_bancari cb
WHERE c.conto_bancario_id IS NULL
  AND cb.compagnia_id = c.id
  AND replace(upper(cb.iban), ' ', '') = c.iban
  AND EXISTS (SELECT 1 FROM imp_comp_xlsx s WHERE lower(s.codice) = lower(c.codice));

UPDATE public.compagnia_rapporti r SET
  conto_bancario_id = c.conto_bancario_id,
  iban_dedicato = c.iban,
  updated_at = now()
FROM public.compagnie c
JOIN imp_comp_xlsx s ON lower(s.codice) = lower(c.codice)
WHERE r.compagnia_id = c.id
  AND (r.is_principale OR lower(r.codice_rapporto) = lower(c.codice))
  AND c.conto_bancario_id IS NOT NULL
  AND r.conto_bancario_id IS DISTINCT FROM c.conto_bancario_id;

SELECT
  (SELECT count(*) FROM public.compagnie c JOIN imp_comp_xlsx s ON lower(s.codice) = lower(c.codice)) AS agenzie_excel_in_db,
  (SELECT count(*) FROM public.compagnia_rapporti r JOIN public.compagnie c ON c.id = r.compagnia_id JOIN imp_comp_xlsx s ON lower(s.codice) = lower(c.codice) WHERE lower(r.codice_rapporto) = lower(c.codice)) AS mandati_con_codice_agenzia;

COMMIT;

